<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import {ElMessage} from 'element-plus';
import {ArrowDown,ChatDotRound,CircleCheckFilled,Collection,Connection,DataAnalysis,Drizzling,Grid,House,InfoFilled,Loading,Menu,Monitor,Odometer,Setting,Sunny,User,VideoPlay,Warning} from '@element-plus/icons-vue';
import {api,RequestError} from './api';
import ZoneTrendChart from './ZoneTrendChart.vue';
import CropManagement from './CropManagement.vue';
import ZoneMonitoring from './ZoneMonitoring.vue';
import KnowledgeFusion from './KnowledgeFusion.vue';
import type {CropProfile,Device,State,Task} from '../../server/domain';

type PublicDevice=Device&{sampleCount:number};
type PublicState=Omit<State,'devices'|'messages'|'forecasts'>&{devices:PublicDevice[];aiConfigured:boolean};
type Locale='zh'|'uz';
type ZoneStatus='normal'|'dry'|'irrigating'|'offline';

const locale=ref<Locale>('zh'),layout=ref<9|16>(16),activeNav=ref('overview'),selectedId=ref('B02');
const state=ref<PublicState>(),cropProfiles=ref<CropProfile[]>([]),loading=ref(true),connectionError=ref(''),taskBusy=ref(false),bulkTaskId=ref(''),singleTaskId=ref('');
let poll:ReturnType<typeof setInterval>|undefined,loadBusy=false;

const copy={
 zh:{brand:'分区灌溉',slogan:'分 区 感 知 · 精 准 灌 溉',overview:'总览',zones:'分区监控',fusion:'知识融合',analytics:'数据分析',crops:'作物参数',devices:'设备管理',settings:'系统设置',title:'16 个分区 · 运行总览',zoneCount:'分区总数',online:'在线设备',warnings:'异常提醒',currentTime:'更新时间',bulk:'批量灌溉',operator:'操作员',live:'实时数据',control:'灌溉控制',info:'设备信息',moisture:'土壤湿度',temperature:'温度',light:'光照',humidity:'空气湿度',trend:'土壤湿度趋势（近12小时）',evidence:'决策依据',start:'启动仿真灌溉',demo:'此为仿真模式，仅用于演示与教学',normal:'正常',dry:'偏干',irrigating:'灌溉中',offline:'离线',deviceOnline:'设备在线',soon:'该模块将在下一阶段完成',taskCreated:'灌溉任务已创建'},
 uz:{brand:'Hududiy sug‘orish',slogan:'H U D U D  N A Z O R A T I  ·  A N I Q  S U G‘O R I S H',overview:'Umumiy ko‘rinish',zones:'Hududlar nazorati',fusion:'Bilimlar integratsiyasi',analytics:'Ma’lumotlar tahlili',crops:'Ekin parametrlari',devices:'Qurilmalar',settings:'Tizim sozlamalari',title:'16 hudud · Ishlash holati',zoneCount:'Hududlar soni',online:'Onlayn qurilmalar',warnings:'Ogohlantirishlar',currentTime:'Yangilanish vaqti',bulk:'Ommaviy sug‘orish',operator:'Operator',live:'Jonli ma’lumotlar',control:'Sug‘orish nazorati',info:'Qurilma ma’lumoti',moisture:'Tuproq namligi',temperature:'Harorat',light:'Yoritish',humidity:'Havo namligi',trend:'Tuproq namligi dinamikasi (12 soat)',evidence:'Qaror asoslari',start:'Simulyatsion sug‘orishni boshlash',demo:'Simulyatsiya rejimi: faqat namoyish va ta’lim uchun',normal:'Me’yorda',dry:'Quruq',irrigating:'Sug‘orilmoqda',offline:'Oflayn',deviceOnline:'Qurilma onlayn',soon:'Bu bo‘lim keyingi bosqichda tayyorlanadi',taskCreated:'Sug‘orish vazifasi yaratildi'}
} as const;
const english={overview:'Overview',zones:'Zones',fusion:'Knowledge Fusion',analytics:'Analytics',crops:'Crop Parameters',devices:'Devices',settings:'Settings',title:'16-Zone Operations Wall',zoneCount:'Zones',online:'Online',warnings:'Warnings',currentTime:'Current Time',bulk:'Bulk Irrigation',live:'Live Data',control:'Irrigation',info:'Device Info',moisture:'Soil Moisture',temperature:'Temperature',light:'Light',humidity:'Air Humidity',trend:'Soil Moisture Trend (Last 12 Hours)',evidence:'Decision Evidence',start:'Start Simulated Irrigation',demo:'Simulation Mode for Demo and Education Only'} as const;
const t=computed(()=>copy[locale.value]);
const uzNames:Record<string,string>={A01:'Salat A1',A02:'Pak-choy A2',A03:'Makkajo‘xori A3',A04:'Rayhon A4',B01:'Pomidor B1',B02:'Pomidor B2',B03:'Pomidor B3',B04:'Qulupnay B4',C01:'Bodring C1',C02:'Qovun C2',C03:'Bodring C3',C04:'Qovun C4',D01:'Ismaloq D1',D02:'Ko‘k piyoz D2',D03:'Makkajo‘xori D3',D04:'Makkajo‘xori D4'};
const cropImage=(device:PublicDevice)=>device.cropId==='tomato'?'/crop-tomato.png':['cucumber','pepper'].includes(device.cropId)?'/crop-pepper.png':['basil','coriander','green-onion'].includes(device.cropId)?'/crop-herbs.png':['lettuce','bok-choy','broccoli','spinach','celery'].includes(device.cropId)?'/crop-lettuce.png':'/planter.png';
const zoneName=(device:PublicDevice)=>locale.value==='zh'?device.name:uzNames[device.id]||device.nameEn;
const profileFor=(device:PublicDevice)=>cropProfiles.value.find(profile=>profile.id===device.cropId);
const isTaskRunning=(id:string)=>state.value?.tasks.some(task=>['pending','running'].includes(task.status)&&task.results.some(result=>result.deviceId===id&&!['success','failed'].includes(result.status)))??false;
const statusOf=(device:PublicDevice):ZoneStatus=>!device.online?'offline':isTaskRunning(device.id)?'irrigating':device.moisture<(profileFor(device)?.moisture.targetMin??38)?'dry':'normal';
const statusLabel=(status:ZoneStatus)=>t.value[status],statusEn=(status:ZoneStatus)=>({normal:'Normal',dry:'Dry',irrigating:'Irrigating',offline:'Offline'})[status];
const devices=computed(()=>state.value?.devices??[]),visibleDevices=computed(()=>devices.value.slice(0,layout.value)),selected=computed(()=>devices.value.find(item=>item.id===selectedId.value)||devices.value[0]);
const activeWaterTasks=computed(()=>(state.value?.tasks??[]).filter(task=>task.type==='water'&&['pending','running'].includes(task.status)));
const bulkRunning=computed(()=>activeWaterTasks.value.some(task=>task.id===bulkTaskId.value||(!bulkTaskId.value&&task.results.length>1)));
const selectedRunning=computed(()=>Boolean(selected.value&&activeWaterTasks.value.some(task=>task.results.some(result=>result.deviceId===selected.value!.id&&!['success','failed'].includes(result.status)))));
const selectedIrrigation=computed(()=>{if(!selected.value)return;for(const task of state.value?.tasks??[]){if(task.type!=='water')continue;const result=task.results.find(item=>item.deviceId===selected.value!.id&&typeof item.targetMoisture==='number');if(result)return result;}});
const irrigationRemaining=computed(()=>selectedIrrigation.value&&selected.value&&['pending','running'].includes(selectedIrrigation.value.status)?Math.max(0,Math.ceil((selectedIrrigation.value.targetMoisture-selected.value.moisture)/10)):0);
const irrigationMessage=computed(()=>{const message=selectedIrrigation.value?.message;if(message==='TARGET_MOISTURE_REACHED')return locale.value==='zh'?'已达到目标湿度':'Maqsad namlikka erishildi';if(message==='MAX_VOLUME_REACHED')return locale.value==='zh'?'达到最大安全水量':'Maksimal xavfsiz suv hajmi';if(message==='MAX_DURATION_REACHED')return locale.value==='zh'?'达到最大运行时间':'Maksimal ish vaqti';if(message==='DEVICE_OFFLINE')return locale.value==='zh'?'设备离线，已停止':'Qurilma oflayn, to‘xtatildi';return locale.value==='zh'?'闭环灌溉进行中':'Yopiq siklli sug‘orish';});
const onlineCount=computed(()=>devices.value.filter(item=>item.online).length),warningCount=computed(()=>devices.value.filter(item=>['dry','offline'].includes(statusOf(item))).length);
const timeLabel=computed(()=>state.value?new Date(state.value.clock).toLocaleString(locale.value==='zh'?'zh-CN':'uz-UZ',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'--');
const navItems=computed(()=>[{id:'overview',icon:House,label:t.value.overview,en:english.overview},{id:'zones',icon:Connection,label:t.value.zones,en:english.zones},{id:'fusion',icon:ChatDotRound,label:t.value.fusion,en:english.fusion},{id:'analytics',icon:DataAnalysis,label:t.value.analytics,en:english.analytics},{id:'crops',icon:Collection,label:t.value.crops,en:english.crops},{id:'devices',icon:Monitor,label:t.value.devices,en:english.devices},{id:'settings',icon:Setting,label:t.value.settings,en:english.settings}]);
const selectedProfile=computed(()=>selected.value?profileFor(selected.value):undefined);
const evidenceLines=computed(()=>{if(!selected.value||!selectedProfile.value)return [];const device=selected.value,profile=selectedProfile.value;const stage={seedling:['幼苗期','Ko‘chat davri','Seedling'],vegetative:['营养生长期','Vegetativ davr','Vegetative'],flowering:['开花期','Gullash davri','Flowering'],fruiting:['结果期','Mevalash davri','Fruiting']}[device.growthStage];return locale.value==='zh'?[`当前湿度 ${device.moisture.toFixed(0)}%，目标范围 ${profile.moisture.targetMin}–${profile.moisture.targetMax}%`,`当前温度 ${device.temperature}°C，适宜范围 ${profile.temperature.optimalMin}–${profile.temperature.optimalMax}°C`,`当前生长阶段：${stage[0]}；作物参数版本 v${profile.version}`,`单次灌溉上限 ${profile.irrigation.maxVolume} mL，最短间隔 ${profile.irrigation.minIntervalMinutes} 分钟`]:[`Joriy namlik ${device.moisture.toFixed(0)}%, maqsad ${profile.moisture.targetMin}–${profile.moisture.targetMax}%`,`Joriy harorat ${device.temperature}°C, mos oraliq ${profile.temperature.optimalMin}–${profile.temperature.optimalMax}°C`,`O‘sish bosqichi: ${stage[1]}; parametr versiyasi v${profile.version}`,`Sug‘orish limiti ${profile.irrigation.maxVolume} mL, interval ${profile.irrigation.minIntervalMinutes} daqiqa`];});
const evidenceEnglish=computed(()=>{if(!selected.value||!selectedProfile.value)return [];const device=selected.value,profile=selectedProfile.value;return [`Current ${device.moisture.toFixed(0)}%; target ${profile.moisture.targetMin}–${profile.moisture.targetMax}%`,`Current ${device.temperature}°C; optimal ${profile.temperature.optimalMin}–${profile.temperature.optimalMax}°C`,`Growth stage: ${device.growthStage}; profile version v${profile.version}`,`Max ${profile.irrigation.maxVolume} mL; minimum interval ${profile.irrigation.minIntervalMinutes} minutes`];});
function errorText(error:unknown){return error instanceof RequestError?error.message:'Operation failed';}
async function load(){if(loadBusy)return;loadBusy=true;try{state.value=await api<PublicState>('/state');connectionError.value='';if(state.value.devices.length&&!state.value.devices.some(d=>d.id===selectedId.value))selectedId.value=state.value.devices[0].id;}catch(error){connectionError.value=errorText(error);}finally{loading.value=false;loadBusy=false;}}
async function loadCropProfiles(){try{cropProfiles.value=await api<CropProfile[]>('/crop-profiles');}catch(error){connectionError.value=errorText(error);}}
function navigate(id:string){if(!['overview','zones','fusion','crops'].includes(id)){ElMessage.info(t.value.soon);return;}activeNav.value=id;}
async function createWaterTask(ids:string[],kind:'bulk'|'single'){if(!state.value||taskBusy.value)return;const targets=ids.filter(id=>devices.value.find(d=>d.id===id)?.online);if(!targets.length){ElMessage.warning(locale.value==='zh'?'没有需要灌溉的在线分区':'Sug‘orish kerak bo‘lgan onlayn hudud yo‘q');return;}taskBusy.value=true;try{const task=await api<Task>('/tasks',{deviceIds:targets,type:'water',requestId:crypto.randomUUID(),version:state.value.version});if(kind==='bulk')bulkTaskId.value=task.id;else singleTaskId.value=task.id;await load();ElMessage.success(locale.value==='zh'?'闭环灌溉任务已创建，将在达到目标湿度后自动停止':'Yopiq siklli sug‘orish boshlandi');}catch(error){ElMessage.error(errorText(error));}finally{taskBusy.value=false;}}
function handleZoneIrrigation(payload:{ids:string[];kind:'bulk'|'single'}){createWaterTask(payload.ids,payload.kind);}
async function stopWaterTask(taskId:string){if(taskBusy.value)return;taskBusy.value=true;try{await api(`/tasks/${taskId}/stop`,{},'POST');await load();ElMessage.success(locale.value==='zh'?'灌溉任务已手动停止':'Sug‘orish vazifasi to‘xtatildi');}catch(error){ElMessage.error(errorText(error));}finally{taskBusy.value=false;}}
function bulkIrrigate(){createWaterTask(devices.value.filter(d=>d.online&&d.moisture<(profileFor(d)?.moisture.targetMin??45)).map(d=>d.id),'bulk');}
onMounted(async()=>{await Promise.all([load(),loadCropProfiles()]);poll=setInterval(load,2000);});onBeforeUnmount(()=>{if(poll)clearInterval(poll);});
</script>

<template><div class="desktop-app">
 <header class="topbar"><div class="brand-block"><img src="/leaf-logo.png" alt=""><div class="brand-name"><strong>{{t.brand}}</strong><span>Zoned Irrigation</span></div><div class="brand-slogan"><b>{{t.slogan}}</b><span>Sense by Zone · Irrigate Precisely</span></div></div><div class="topbar-meta"><div class="site-name"><span class="round-icon"><img src="/leaf-logo.png" alt=""></span><p><b>{{locale==='zh'?'农业示范温室':'Namoyish issiqxonasi'}}</b><small>Agricultural Greenhouse</small></p></div><div class="date-block"><b>{{timeLabel}}</b><small>{{locale==='zh'?'实时仿真时间':'Real vaqtdagi simulyatsiya'}}</small></div><el-dropdown trigger="click" @command="(value:Locale)=>locale=value"><button class="language-button" aria-label="Language"><span class="globe">◎</span><span><b>{{locale==='zh'?'中文':'O‘zbekcha'}}</b><small>{{locale==='zh'?'O‘zbekcha':'中文'}}</small></span><el-icon><ArrowDown/></el-icon></button><template #dropdown><el-dropdown-menu><el-dropdown-item command="zh">中文</el-dropdown-item><el-dropdown-item command="uz">O‘zbekcha</el-dropdown-item></el-dropdown-menu></template></el-dropdown><button class="operator"><span class="avatar"><el-icon><User/></el-icon></span><b>{{t.operator}}</b><el-icon><ArrowDown/></el-icon></button></div></header>
 <div class="workspace"><aside class="sidebar"><nav aria-label="Primary navigation"><button v-for="item in navItems" :key="item.id" :class="{active:activeNav===item.id}" @click="navigate(item.id)"><el-icon><component :is="item.icon"/></el-icon><span><b>{{item.label}}</b><small>{{item.en}}</small></span></button></nav><div class="sidebar-signature"><img src="/leaf-logo.png" alt=""><b>数据赋能农业</b><span>Data for Knowledge</span><b>科学养护</b><span>Data &amp; Knowledge<br>for Better Growth</span></div></aside>
 <main v-if="activeNav==='overview'" class="overview-page"><div v-if="connectionError" class="connection-error" role="alert">{{connectionError}} <button @click="load">重试 / Retry</button></div><section class="overview-toolbar"><div class="page-title"><h1>{{t.title}}</h1><p>{{english.title}}</p></div><div class="summary-strip"><div class="summary-item"><span class="summary-icon green"><img src="/leaf-logo.png" alt=""></span><p><strong>{{devices.length}}</strong><b>{{t.zoneCount}}</b><small>{{english.zoneCount}}</small></p></div><div class="summary-item"><span class="summary-icon blue"><el-icon><Connection/></el-icon></span><p><strong>{{onlineCount}}</strong><b>{{t.online}}</b><small>{{english.online}}</small></p></div><div class="summary-item"><span class="summary-icon orange"><el-icon><Warning/></el-icon></span><p><strong>{{warningCount}}</strong><b>{{t.warnings}}</b><small>{{english.warnings}}</small></p></div></div><div class="updated"><small>{{t.currentTime}}<br><span>{{english.currentTime}}</span></small><b>{{timeLabel}}</b></div><div class="layout-toggle"><button :class="{active:layout===9}" @click="layout=9"><el-icon><Grid/></el-icon><span>9 {{locale==='zh'?'宫格':'katak'}}</span></button><button :class="{active:layout===16}" @click="layout=16"><el-icon><Menu/></el-icon><span>16 {{locale==='zh'?'宫格':'katak'}}</span></button></div><button class="primary-action" :class="{'is-irrigating':bulkRunning}" :disabled="taskBusy||bulkRunning" @click="bulkIrrigate"><el-icon v-if="bulkRunning" class="is-loading"><Loading/></el-icon><el-icon v-else><VideoPlay/></el-icon><span><b>{{bulkRunning?t.irrigating:t.bulk}}</b><small>{{bulkRunning?'Irrigating':english.bulk}}</small></span></button></section>
 <div v-if="loading" class="loading-panel">正在连接分区灌溉平台…</div><div v-else-if="selected" class="dashboard-body"><section :class="['zone-grid',`layout-${layout}`]"><button v-for="zone in visibleDevices" :key="zone.id" :class="['zone-card',statusOf(zone),{selected:selectedId===zone.id}]" @click="selectedId=zone.id"><div class="zone-heading"><strong>{{zone.id}}</strong><span class="status"><i></i><b>{{statusLabel(statusOf(zone))}}</b><small>{{statusEn(statusOf(zone))}}</small></span></div><div class="zone-name"><b>{{zoneName(zone)}}</b><small>{{zone.nameEn}}</small></div><div class="zone-reading"><img :src="cropImage(zone)" :alt="zoneName(zone)"><strong>{{zone.online?`${zone.moisture.toFixed(0)}%`:'--'}}</strong></div><div class="zone-meta"><span><el-icon><Odometer/></el-icon>{{zone.online?`${zone.temperature}°C`:'--'}}</span><span><el-icon><Sunny/></el-icon>{{zone.online?`${zone.light*800} lux`:'--'}}</span></div></button></section>
 <aside class="detail-panel"><div class="detail-head"><div><strong>{{selected.id}}</strong><span :class="['detail-status',statusOf(selected)]"><i></i>{{statusLabel(statusOf(selected))}}<small>{{statusEn(statusOf(selected))}}</small></span></div><div class="selected-crop"><img :src="cropImage(selected)" :alt="zoneName(selected)"><p><b>{{zoneName(selected)}}</b><small>{{selected.nameEn}} · {{selectedProfile?.nameEn}}</small></p></div><span class="online-state"><i></i>{{selected.online?t.deviceOnline:t.offline}}<small>{{selected.online?'Device Online':'Offline'}}</small></span></div><div class="detail-tabs"><button class="active"><b>{{t.live}}</b><small>{{english.live}}</small></button><button @click="ElMessage.info(t.soon)"><b>{{t.control}}</b><small>{{english.control}}</small></button><button @click="ElMessage.info(t.soon)"><b>{{t.info}}</b><small>{{english.info}}</small></button></div><section v-if="selectedIrrigation" :class="['irrigation-live',selectedIrrigation.status]"><div class="irrigation-live-head"><span><el-icon :class="{'is-loading':selectedRunning}"><Loading v-if="selectedRunning"/><CircleCheckFilled v-else/></el-icon><b>{{irrigationMessage}}</b><small>{{selectedRunning?'Closed-loop irrigation':'Last irrigation result'}}</small></span><strong>{{selectedIrrigation.progress}}%</strong></div><div class="irrigation-progress"><i :style="{width:`${selectedIrrigation.progress}%`}"></i></div><div class="irrigation-facts"><span><b>{{selected.moisture.toFixed(0)}}% → {{selectedIrrigation.targetMoisture}}%</b><small>{{locale==='zh'?'当前 → 目标':'Joriy → Maqsad'}}</small></span><span><b>{{selectedIrrigation.delivered.toFixed(0)}} / {{selectedIrrigation.maxVolume}} mL</b><small>{{locale==='zh'?'已灌 / 上限':'Berildi / Limit'}}</small></span><span><b>{{selectedRunning?`${irrigationRemaining}s`:`${selectedIrrigation.elapsedSeconds}s`}}</b><small>{{selectedRunning?(locale==='zh'?'预计剩余':'Taxminiy qoldi'):(locale==='zh'?'运行时间':'Ish vaqti')}}</small></span></div></section><div class="metrics-grid"><div><span class="metric-symbol green"><el-icon><Drizzling/></el-icon></span><p><b>{{t.moisture}}</b><small>{{english.moisture}} · {{selectedProfile?.moisture.targetMin}}–{{selectedProfile?.moisture.targetMax}}%</small><strong :class="{orange:selected.moisture<(selectedProfile?.moisture.targetMin??35)}">{{selected.online?`${selected.moisture.toFixed(0)}%`:'--'}}</strong></p></div><div><span class="metric-symbol green"><el-icon><Odometer/></el-icon></span><p><b>{{t.temperature}}</b><small>{{english.temperature}} · {{selectedProfile?.temperature.optimalMin}}–{{selectedProfile?.temperature.optimalMax}}°C</small><strong :class="{orange:selectedProfile&&(selected.temperature<selectedProfile.temperature.optimalMin||selected.temperature>selectedProfile.temperature.optimalMax)}">{{selected.online?`${selected.temperature}°C`:'--'}}</strong></p></div><div><span class="metric-symbol orange"><el-icon><Sunny/></el-icon></span><p><b>{{t.light}}</b><small>{{english.light}} · {{selectedProfile?.lightHours.min}}–{{selectedProfile?.lightHours.max}} h/day</small><strong>{{selected.online?`${selected.light*800} lux`:'--'}}</strong></p></div><div><span class="metric-symbol green"><el-icon><CircleCheckFilled/></el-icon></span><p><b>{{locale==='zh'?'参数版本':'Parametr versiyasi'}}</b><small>Crop Profile</small><strong>v{{selectedProfile?.version??'--'}}</strong></p></div></div><section class="trend-panel"><h2>{{t.trend}}</h2><p>{{english.trend}}</p><ZoneTrendChart :device="selected"/></section><section class="evidence-panel"><h2><img src="/leaf-logo.png" alt="">{{t.evidence}} <span>/ {{english.evidence}}</span></h2><ul><li v-for="(line,index) in evidenceLines" :key="line"><b>{{line}}</b><small>{{evidenceEnglish[index]}}</small></li></ul></section><button class="start-button" :class="{'is-irrigating':selectedRunning}" :disabled="taskBusy||selectedRunning||!selected.online||selected.moisture>=(selectedProfile?.moisture.targetMin??100)" @click="createWaterTask([selected.id],'single')"><el-icon v-if="selectedRunning" class="is-loading"><Loading/></el-icon><el-icon v-else><VideoPlay/></el-icon><span><b>{{selectedRunning?t.irrigating:t.start}}</b><small>{{selectedRunning?'Irrigating':english.start}}</small></span></button><div class="demo-note"><el-icon><InfoFilled/></el-icon><span>{{t.demo}}<small>{{english.demo}}</small></span></div></aside></div></main><ZoneMonitoring v-else-if="activeNav==='zones'" :locale="locale" :devices="devices" :profiles="cropProfiles" :tasks="state?.tasks??[]" :busy="taskBusy" @irrigate="handleZoneIrrigation" @stop="stopWaterTask"/><KnowledgeFusion v-else-if="activeNav==='fusion'" :locale="locale" :devices="devices" :profiles="cropProfiles" :tasks="state?.tasks??[]" :ai-configured="state?.aiConfigured??false" @execute="handleZoneIrrigation"/><CropManagement v-else-if="activeNav==='crops'" :locale="locale" :devices="devices" @changed="loadCropProfiles"/></div>
</div></template>
